# Remove extra friends from Venmo
for email in friends_to_remove:
    apis.venmo.remove_friend(user_email=email, access_token=venmo_token)

# Extract emails of phone contacts who are friends (relationship includes 'friend')
phone_friends_emails = set()
for contact in contacts:
    if 'friend' in contact.get('relationships', []):
        email = contact.get('email')
        if email:
            phone_friends_emails.add(email.lower())

# Extract emails of current Venmo friends
venmo_friends_emails = set()
for friend in venmo_friends:
    email = friend.get('email')
    if email:
        venmo_friends_emails.add(email.lower())

print("Phone friends emails:", phone_friends_emails)
print("Venmo friends emails:", venmo_friends_emails)

# Add missing friends on Venmo
for email in friends_to_add:
    apis.venmo.add_friend(user_email=email, access_token=venmo_token)

